using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using UnityEditor;
using UnityEngine;

namespace Uninarok.Networking.Editor
{
    /// <summary>
    /// Turns the Hercules packet length fixture into <c>Core/Protocol/HerculesPacketTable.g.cs</c>
    /// (SPEC-0001 FR-18, FR-19; plan 4.8). The generated file is never edited by hand: change the JSON and rerun.
    /// </summary>
    public static class HerculesPacketTableGenerator
    {
        public const string FixtureRelativePath = "docs/specs/0001-networking-core/fixtures/hercules-packetlen-20220406.json";
        public const string OutputAssetPath = "Assets/Scripts/Networking/Core/Protocol/HerculesPacketTable.g.cs";

        private static readonly Regex Entry = new Regex("\"(0x[0-9A-Fa-f]{4})\"\\s*:\\s*(-?\\d+)", RegexOptions.Compiled);
        private static readonly Regex Source = new Regex("\"_source\"\\s*:\\s*\"([^\"]*)\"", RegexOptions.Compiled);

        [MenuItem("Uninarok/Networking/Regenerate Hercules Packet Table")]
        public static void Regenerate()
        {
            string projectRoot = Directory.GetParent(Application.dataPath).Parent.FullName;
            string json = File.ReadAllText(Path.Combine(projectRoot, FixtureRelativePath));
            string source = Generate(json);

            string output = Path.GetFullPath(Path.Combine(Application.dataPath, "..", OutputAssetPath));
            File.WriteAllText(output, source, new UTF8Encoding(false));
            AssetDatabase.ImportAsset(OutputAssetPath);
            Debug.Log("Hercules packet table regenerated: " + OutputAssetPath);
        }

        /// <summary>
        /// Validates the fixture and returns the C# source of the table. Every value must be -1 (variable) or at least 2
        /// (fixed total length including the ID) and fit a <c>short</c>; IDs must be unique.
        /// Throws <see cref="InvalidDataException"/> with the offending ID otherwise.
        /// </summary>
        public static string Generate(string fixtureJson)
        {
            var lengths = new SortedDictionary<ushort, int>();
            foreach (Match m in Entry.Matches(fixtureJson))
            {
                ushort id = Convert.ToUInt16(m.Groups[1].Value.Substring(2), 16);
                int value = int.Parse(m.Groups[2].Value);
                if (lengths.ContainsKey(id))
                    throw new InvalidDataException($"Duplicate packet ID 0x{id:X4}");
                if (id == 0)
                    throw new InvalidDataException("Packet ID 0x0000 must not be in the table (ID 0 is a protocol fault)");
                if (value != -1 && (value < 2 || value > short.MaxValue))
                    throw new InvalidDataException($"Invalid length {value} for packet 0x{id:X4} (expected -1 or 2..{short.MaxValue})");
                lengths.Add(id, value);
            }
            if (lengths.Count == 0)
                throw new InvalidDataException("No packet lengths found in the fixture");

            string origin = Source.Match(fixtureJson).Groups[1].Value;
            var sb = new StringBuilder(64 * 1024);
            sb.Append("// <auto-generated>\n");
            sb.Append("// Generated by Uninarok.Networking.Editor.HerculesPacketTableGenerator (menu: Uninarok/Networking/Regenerate Hercules Packet Table).\n");
            sb.Append("// Source: ").Append(origin).Append("\n");
            sb.Append("// Do not edit by hand: change ").Append(FixtureRelativePath).Append(" and regenerate.\n");
            sb.Append("// </auto-generated>\n\n");
            sb.Append("using Uninarok.Networking.Core.Framing;\n\n");
            sb.Append("namespace Uninarok.Networking.Core.Protocol\n{\n");
            sb.Append("    /// <summary>Packet lengths of the target server (").Append(lengths.Count).Append(" packets). -1 variable, -2 unknown, otherwise the fixed total length.</summary>\n");
            sb.Append("    public sealed class HerculesPacketTable : IPacketLengthTable\n    {\n");
            sb.Append("        public const int PacketCount = ").Append(lengths.Count).Append(";\n\n");

            sb.Append("        private static readonly ushort[] s_ids =\n        {\n");
            AppendValues(sb, lengths.Keys, id => "0x" + id.ToString("X4"));
            sb.Append("        };\n\n");
            sb.Append("        private static readonly short[] s_lengths =\n        {\n");
            AppendValues(sb, lengths.Values, v => v.ToString());
            sb.Append("        };\n\n");

            // Declared after the arrays: static initializers run in textual order.
            sb.Append("        public static readonly HerculesPacketTable Instance = new HerculesPacketTable();\n\n");
            sb.Append("        private readonly short[] _table = Build();\n\n");
            sb.Append("        /// <summary>-1 variable, -2 unknown, otherwise the fixed total length. One array index.</summary>\n");
            sb.Append("        public int GetLength(ushort packetId) => _table[packetId];\n\n");
            sb.Append("        private static short[] Build()\n        {\n");
            sb.Append("            var table = new short[65536];\n");
            sb.Append("            for (int i = 0; i < table.Length; i++) table[i] = -2;\n");
            sb.Append("            for (int i = 0; i < s_ids.Length; i++) table[s_ids[i]] = s_lengths[i];\n");
            sb.Append("            return table;\n");
            sb.Append("        }\n");
            sb.Append("    }\n}\n");
            return sb.ToString();
        }

        private static void AppendValues<T>(StringBuilder sb, IEnumerable<T> values, Func<T, string> format)
        {
            int perLine = 0;
            foreach (T v in values)
            {
                if (perLine == 0) sb.Append("            ");
                sb.Append(format(v)).Append(',');
                if (++perLine == 12) { sb.Append('\n'); perLine = 0; }
                else sb.Append(' ');
            }
            if (perLine != 0) { sb.Length -= 1; sb.Append('\n'); }
        }
    }
}
